function CloseTabClicked() {
    var win = parent;
    win.close();
}

const FULLSCREEN_HELPER_ROOT_URL = "http://127.0.0.1:8767";
const FULLSCREEN_HELPER_BASE_URL = FULLSCREEN_HELPER_ROOT_URL + "/fullscreen";
let helperFullscreenState = null;
let helperHealthPromise = null;

function getHostWindow() {
    try {
        if (window.top && window.top.document) {
            return window.top;
        }
    } catch (error) {
    }

    try {
        if (parent && parent.document) {
            return parent;
        }
    } catch (error) {
    }

    return window;
}

function getFullscreenElement(doc) {
    return doc.fullscreenElement || doc.webkitFullscreenElement || doc.msFullscreenElement || doc.mozFullScreenElement;
}

function setFullscreenIcon(isFullscreen) {
    document.getElementById("iconOn").style.display = isFullscreen ? "none" : "block";
    document.getElementById("iconOff").style.display = isFullscreen ? "block" : "none";
}

function getCurrentFullscreenState() {
    if (helperFullscreenState !== null) {
        return helperFullscreenState;
    }

    const hostWindow = getHostWindow();
    return !!getFullscreenElement(hostWindow.document);
}

function prepareHostForFullscreen(triggerElement) {
    const hostWindow = getHostWindow();
    const doc = hostWindow.document;

    try {
        hostWindow.focus();
    } catch (error) {
    }

    try {
        window.focus();
    } catch (error) {
    }

    try {
        if (doc.documentElement && doc.documentElement.focus) {
            doc.documentElement.focus();
        }
    } catch (error) {
    }

    try {
        if (doc.body && doc.body.focus) {
            doc.body.focus();
        }
    } catch (error) {
    }

    try {
        if (triggerElement && triggerElement.focus) {
            triggerElement.focus();
        }
    } catch (error) {
    }
}

function syncFullscreenIcon() {
    helperFullscreenState = null;
    setFullscreenIcon(getCurrentFullscreenState());
}

function checkFullscreenHelperHealth() {
    if (!helperHealthPromise) {
        helperHealthPromise = fetch(FULLSCREEN_HELPER_ROOT_URL + "/health", {
            method: "GET",
            cache: "no-store"
        }).then(function(response) {
            if (!response.ok) {
                throw new Error("Fullscreen helper health returned " + response.status);
            }
            return response.json();
        }).then(function(payload) {
            if (!payload || !payload.ok) {
                throw new Error("Fullscreen helper is not healthy.");
            }
            return payload;
        }).catch(function(error) {
            helperHealthPromise = null;
            throw error;
        });
    }

    return helperHealthPromise;
}

function invokeFullscreenHelper(action) {
    return checkFullscreenHelperHealth().then(function() {
        return fetch(FULLSCREEN_HELPER_BASE_URL + "/" + action, {
            method: "POST",
            cache: "no-store"
        }).then(function(response) {
            if (!response.ok) {
                throw new Error("Fullscreen helper returned " + response.status);
            }

            return response.json().catch(function() {
                return { ok: true };
            });
        });
    });
}

function requestHostFullscreen() {
    const hostWindow = getHostWindow();
    const doc = hostWindow.document;
    const elem = doc.documentElement;

    if (elem.requestFullscreen) {
        return elem.requestFullscreen();
    }
    if (elem.msRequestFullscreen) {
        return elem.msRequestFullscreen();
    }
    if (elem.mozRequestFullScreen) {
        return elem.mozRequestFullScreen();
    }
    if (elem.webkitRequestFullscreen) {
        return elem.webkitRequestFullscreen(Element.ALLOW_KEYBOARD_INPUT);
    }

    return Promise.reject(new Error("Fullscreen API is not available."));
}

function exitHostFullscreen() {
    const hostWindow = getHostWindow();
    const doc = hostWindow.document;

    if (doc.exitFullscreen) {
        return doc.exitFullscreen();
    }
    if (doc.msExitFullscreen) {
        return doc.msExitFullscreen();
    }
    if (doc.mozCancelFullScreen) {
        return doc.mozCancelFullScreen();
    }
    if (doc.webkitExitFullscreen) {
        return doc.webkitExitFullscreen();
    }

    return Promise.reject(new Error("Exit fullscreen is not available."));
}

function FullScreenClicked() {
    requestHostFullscreen().catch(function(error) {
        console.warn("Entering fullscreen failed.", error);
    });
}

function ExitFullScreenClicked() {
    exitHostFullscreen().catch(function(error) {
        console.warn("Exiting fullscreen failed.", error);
    });
}

function HandleFullscreenPointerDown(event) {
    prepareHostForFullscreen(event.currentTarget);
}

function FullScreenToggle(event) {
    const triggerElement = event && event.currentTarget ? event.currentTarget : null;
    const nextAction = getCurrentFullscreenState() ? "exit" : "enter";

    prepareHostForFullscreen(triggerElement);

    invokeFullscreenHelper(nextAction).then(function() {
        helperFullscreenState = nextAction === "enter";
        setFullscreenIcon(helperFullscreenState);
    }).catch(function(helperError) {
        console.warn("Fullscreen helper failed, falling back to browser fullscreen.", helperError);

        const hostWindow = getHostWindow();
        const doc = hostWindow.document;

        if (!getFullscreenElement(doc)) {
            requestHostFullscreen().catch(function(error) {
                console.warn("Fullscreen toggle failed while entering fullscreen.", error);
            });
        } else {
            exitHostFullscreen().catch(function(error) {
                console.warn("Fullscreen toggle failed while exiting fullscreen.", error);
            });
        }

        setTimeout(syncFullscreenIcon, 100);
    });
}

window.onload = function () {
    const hostWindow = getHostWindow();
    const doc = hostWindow.document;

    ["fullscreenchange", "webkitfullscreenchange", "msfullscreenchange", "mozfullscreenchange"].forEach(function(eventName) {
        doc.addEventListener(eventName, syncFullscreenIcon);
    });

    syncFullscreenIcon();
};

function ShowAlertClicked() {
    alert("new alert window");
}

function windowOpen() {
    var text = "<p>A new window!<br></p>";
    var myWindow = window.open("about:blank", "secondWindow", "width=300,height=400,left=100,top=200");
    myWindow.document.write(text);
    myWindow.focus();
}
